    internalLinks: [{ 'label': 'Vérifier une réponse IA en comptabilité, méthode EC', 'href': '/blog/verifier-reponse-ia-comptabilite' }, { 'label': 'Préparer des données confidentielles pour une IA, contexte EC', 'href': '/blog/ia-comptabilite-confidentialite-donnees' }],
    motsSources: { 'h2a-nep-230': 'documentation de l’audit', 'dila-a821-66': 'documentation de l’audit' },
